import{_ as o,c as t,o as d,b2 as c}from"./chunks/framework.CUhoHPxN.js";const u=JSON.parse('{"title":"C7TreeSelect（C7 树选择）设计说明","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-07-c7-tree-select-design.md","filePath":"superpowers/specs/2026-05-07-c7-tree-select-design.md"}'),r={name:"superpowers/specs/2026-05-07-c7-tree-select-design.md"};function a(l,e,s,n,i,g){return d(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="c7treeselect-c7-树选择-设计说明" tabindex="-1">C7TreeSelect（C7 树选择）设计说明 <a class="header-anchor vp-link" href="#c7treeselect-c7-树选择-设计说明" aria-label="Permalink to &quot;C7TreeSelect（C7 树选择）设计说明&quot;">​</a></h1><p><strong>日期</strong>：2026-05-07<br><strong>状态</strong>：已定稿（经 brainstorming 澄清：1A～6A；方案 <strong>A</strong>——独立组件、契约对齐 <code>C7Select</code>）<br><strong>依据</strong>：<code>原始需求/前端/C7树选择.md</code> + 本节 Q&amp;A 与方案对比结论</p><hr><h2 id="_1-背景与目标" tabindex="-1">1. 背景与目标 <a class="header-anchor vp-link" href="#_1-背景与目标" aria-label="Permalink to &quot;1. 背景与目标&quot;">​</a></h2><p>树选择用于<strong>部门 / 分类</strong>等层级数据场景，需在 <strong><code>ElTreeSelect</code></strong> 之上统一：<strong>静态与异步整树加载</strong>、<strong>字段映射</strong>、<strong>多选对外格式</strong>（数组 vs 逗号分隔字符串）、<strong>值类型</strong>，并与现有 <strong><code>C7Select</code></strong> 的加载与命名习惯对齐，降低业务侧心智成本。</p><hr><h2 id="_2-组件边界" tabindex="-1">2. 组件边界 <a class="header-anchor vp-link" href="#_2-组件边界" aria-label="Permalink to &quot;2. 组件边界&quot;">​</a></h2><h3 id="_2-1-职责" tabindex="-1">2.1 职责 <a class="header-anchor vp-link" href="#_2-1-职责" aria-label="Permalink to &quot;2.1 职责&quot;">​</a></h3><ul><li>数据来源：<code>dataList</code>（及别名 <code>options</code>）<strong>优先</strong>；否则通过 <code>fetchData</code> + <code>resultKey</code>（可选 <code>dataFormatter</code>）加载<strong>整棵树</strong>数组。</li><li>将业务字段映射为 <code>ElTreeSelect</code> 所需的 <code>label</code> / <code>value</code> / <code>children</code>：<code>labelKey</code>、<code>valueKey</code>、<code>childrenKey</code>。</li><li>多选：<code>multiple === true</code> 时由 EP 展示 checkbox 行为；对外 <code>v-model</code> / <code>change</code> 支持 <strong><code>separator</code></strong> 逗号字符串或数组（见 §5）。</li><li><code>valueType</code>：<code>auto</code> | <code>string</code> | <code>number</code>，控制对外标量/数组元素类型。</li><li>透传：<code>filterable</code>、<code>filterNodeMethod</code> 及未在保留键中的 <code>ElTreeSelect</code> attrs。</li><li>事件：<code>update:modelValue</code>、<code>change</code>、<code>load-error</code>；若 EP 暴露与下拉可见性相关事件，实现时<strong>可</strong>与 <code>C7Select</code> 一样增加 <code>visible-change</code> / <code>loading-change</code> 透传（以 EP 类型为准，不阻塞一期）。</li><li>暴露：<code>reload()</code>，用于重新请求或刷新静态来源（行为见 §4）。</li></ul><h3 id="_2-2-非职责-一期明确不做" tabindex="-1">2.2 非职责（一期明确不做） <a class="header-anchor vp-link" href="#_2-2-非职责-一期明确不做" aria-label="Permalink to &quot;2.2 非职责（一期明确不做）&quot;">​</a></h3><ul><li><strong>节点懒加载</strong>（<code>lazy</code> + <code>load</code>）、按关键字远程搜树（与 <code>C7Select</code> 的 <code>remote</code> 模式不对齐一期）。</li><li><strong>不</strong>为减小与 <code>C7Select</code> 的重复而一期抽取公共 composable（避免牵动 <code>C7Select</code>）；后续若重复明显再抽离。</li></ul><h3 id="_2-3-与原始需求文档的差异" tabindex="-1">2.3 与原始需求文档的差异 <a class="header-anchor vp-link" href="#_2-3-与原始需求文档的差异" aria-label="Permalink to &quot;2.3 与原始需求文档的差异&quot;">​</a></h3><ul><li>原始需求中的 <strong><code>rangeMerge</code></strong> 与实现对齐时统一为 <strong><code>separator</code></strong>（与 <code>C7Select</code> 一致）；建议在实现阶段同步更新 <code>原始需求/前端/C7树选择.md</code> 中的用词。</li></ul><hr><h2 id="_3-技术选型-已定稿" tabindex="-1">3. 技术选型（已定稿） <a class="header-anchor vp-link" href="#_3-技术选型-已定稿" aria-label="Permalink to &quot;3. 技术选型（已定稿）&quot;">​</a></h2><ul><li><strong>底层组件</strong>：<code>ElTreeSelect</code>（Element Plus）。</li><li><strong>实现策略</strong>：<strong>方案 A</strong>——独立 <code>C7TreeSelect</code> 组件内实现与 <code>C7Select</code> 同类的请求与列表解析逻辑；树专有映射保留在本组件。</li></ul><hr><h2 id="_4-数据流与加载策略" tabindex="-1">4. 数据流与加载策略 <a class="header-anchor vp-link" href="#_4-数据流与加载策略" aria-label="Permalink to &quot;4. 数据流与加载策略&quot;">​</a></h2><ol><li><strong>静态优先</strong>：若 <code>dataList !== undefined</code>（含空数组），以 <code>dataList</code> 为数据源，<strong>不因存在 <code>fetchData</code> 而自动发请求</strong>（与 <code>C7Select</code> 一致）。<code>options</code> 为 <code>dataList</code> 别名；<strong><code>dataList !== undefined</code> 时仅以 <code>dataList</code> 为准</strong>。</li><li><strong>异步整树</strong>：当无有效静态约定下的数据需求时，由 <strong><code>autoLoad</code></strong>（默认与 <code>C7Select</code> 一致：<code>true</code> 时在无静态数据场景挂载后拉取一次，参数为 <code>fetchParams</code> 浅拷贝、<strong>无 <code>query</code></strong>）或 <strong><code>reload()</code></strong> 触发 <code>fetchData</code>。</li><li><strong>解析链</strong>：<code>fetchData</code> 返回值 → 从 <code>response.data</code>（或与项目 axios 封装一致的数据根）上按 <strong><code>resultKey</code></strong> 取数组 → 可选 <strong><code>dataFormatter(list)</code></strong> → <strong><code>mapTreeKeys</code></strong> 生成传入 <code>ElTreeSelect</code> 的 <code>data</code>。</li><li><strong>失败</strong>：请求异常时 <strong><code>emit(&#39;load-error&#39;, error)</code></strong>，树数据保持<strong>上一次成功结果</strong>或空数组；<strong>不</strong>伪造成功。</li><li><strong>加载态</strong>：内部维护 loading 标志；若调用方通过 attrs 传入 <code>loading</code>，以<strong>不破坏 EP 行为</strong>为原则合并（实现细节：优先内部请求态，或与 attrs 做 OR，在 JSDoc 中写清）。</li></ol><hr><h2 id="_5-对外值形态与-valuetype" tabindex="-1">5. 对外值形态与 <code>valueType</code> <a class="header-anchor vp-link" href="#_5-对外值形态与-valuetype" aria-label="Permalink to &quot;5. 对外值形态与 `valueType`&quot;">​</a></h2><h3 id="_5-1-对内" tabindex="-1">5.1 对内 <a class="header-anchor vp-link" href="#_5-1-对内" aria-label="Permalink to &quot;5.1 对内&quot;">​</a></h3><p>与 <code>ElTreeSelect</code> 一致：单选为标量；多选为<strong>数组</strong>（原始 value 类型由节点 <code>valueKey</code> 字段决定）。</p><h3 id="_5-2-对外-v-model-change" tabindex="-1">5.2 对外 <code>v-model</code> / <code>change</code> <a class="header-anchor vp-link" href="#_5-2-对外-v-model-change" aria-label="Permalink to &quot;5.2 对外 `v-model` / `change`&quot;">​</a></h3><div class="vp-table"><table><thead><tr><th>场景</th><th>行为</th></tr></thead><tbody><tr><td>单选</td><td>按 <code>valueType</code> 输出标量；<strong><code>auto</code></strong>：以 <strong>映射后根列表第一条节点</strong>的 <strong><code>valueKey</code> 字段的 JavaScript 类型</strong>为准，将当前选中值转为该类型（无节点或无法取样时退化为 <code>string</code> 或与 <code>C7Select</code> 相同兜底策略）。</td></tr><tr><td>多选且 <strong><code>separator === false</code></strong></td><td>对外为 <strong>数组</strong>；元素类型服从 <code>valueType</code> / <code>auto</code>。</td></tr><tr><td>多选且 <strong><code>separator === true</code></strong></td><td>对外为 <strong>英文逗号分隔字符串</strong>；<strong>空选择</strong>对外为 <strong><code>&#39;&#39;</code></strong>（与 <code>C7Select</code> 一致）。</td></tr></tbody></table></div><h3 id="_5-3-外部值回写" tabindex="-1">5.3 外部值回写 <a class="header-anchor vp-link" href="#_5-3-外部值回写" aria-label="Permalink to &quot;5.3 外部值回写&quot;">​</a></h3><ul><li><strong><code>separator</code></strong> 模式下外部传入字符串：解析为数组再传入 EP；解析规则与 <code>C7Select</code> <strong>对齐</strong>（含「值中含逗号」的文档警示）。</li><li><strong><code>valueType === &#39;number&#39;</code></strong>：对外对内数字一致时的转换与 <code>C7Select</code> 行为对齐，避免浮点与大整数歧义处须在 JSDoc 中注明边界。</li></ul><h3 id="_5-4-多选父子联动" tabindex="-1">5.4 多选父子联动 <a class="header-anchor vp-link" href="#_5-4-多选父子联动" aria-label="Permalink to &quot;5.4 多选父子联动&quot;">​</a></h3><p><strong>默认不传 <code>check-strictly</code></strong> 等与 EP 默认不一致的 prop，即 <strong>与 Element Plus <code>ElTreeSelect</code> 默认父子联动行为一致</strong>（澄清 3A）。业务若需父子独立勾选，自行传 <code>check-strictly</code> 等 attrs。</p><hr><h2 id="_6-props-表-实现清单" tabindex="-1">6. Props 表（实现清单） <a class="header-anchor vp-link" href="#_6-props-表-实现清单" aria-label="Permalink to &quot;6. Props 表（实现清单）&quot;">​</a></h2><p>保留键（不得原样落入 <code>forwardedAttrs</code>）建议与 <code>C7Select</code> 对齐命名：</p><div class="vp-table"><table><thead><tr><th>Prop</th><th>说明</th></tr></thead><tbody><tr><td><code>dataList</code> / <code>options</code></td><td>静态树；别名语义见 §4</td></tr><tr><td><code>fetchData</code> / <code>fetchParams</code> / <code>resultKey</code> / <code>dataFormatter</code> / <code>autoLoad</code></td><td>异步整树加载</td></tr><tr><td><code>labelKey</code> / <code>valueKey</code> / <code>childrenKey</code></td><td>字段映射，默认值建议 <code>label</code> / <code>value</code> / <code>children</code></td></tr><tr><td><code>separator</code></td><td>多选时对外逗号串；非多选无效</td></tr><tr><td><code>valueType</code></td><td><code>&#39;auto&#39;</code> | <code>&#39;string&#39;</code> | <code>&#39;number&#39;</code>，默认 <code>&#39;auto&#39;</code></td></tr><tr><td><code>modelValue</code></td><td>由 <code>v-model</code> 绑定（实现侧标准）</td></tr></tbody></table></div><p>其余 attrs 透传至 <code>ElTreeSelect</code>（<code>inheritAttrs: false</code> + 显式 <code>v-bind</code>）。</p><hr><h2 id="_7-事件与暴露" tabindex="-1">7. 事件与暴露 <a class="header-anchor vp-link" href="#_7-事件与暴露" aria-label="Permalink to &quot;7. 事件与暴露&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>名称</th><th>说明</th></tr></thead><tbody><tr><td><code>update:modelValue</code></td><td>对外形态见 §5</td></tr><tr><td><code>change</code></td><td>载荷与对外 <code>modelValue</code> 一致</td></tr><tr><td><code>load-error</code></td><td>参数为 <code>Error</code> 或 rejection 值</td></tr></tbody></table></div><p><code>defineExpose({ reload })</code>：<code>reload()</code> 触发与首次加载相同的获取逻辑（静态则重新应用映射；异步则重新请求）。</p><hr><h2 id="_8-工程约定" tabindex="-1">8. 工程约定 <a class="header-anchor vp-link" href="#_8-工程约定" aria-label="Permalink to &quot;8. 工程约定&quot;">​</a></h2><ul><li><strong>路径</strong>：<code>quick-ui/src/packages/C7TreeSelect/index.vue</code></li><li><strong>注册</strong>：在 <code>quick-ui/src/packages/index.js</code> 中导出并 <code>installPackages</code> 注册，名称 <strong><code>C7TreeSelect</code></strong></li><li><strong>文档</strong>：实现阶段建议补充 VitePress 通用组件文档（与 <code>c7-select</code> 等并列），本设计稿不替代用户文档。</li></ul><hr><h2 id="_9-验收标准" tabindex="-1">9. 验收标准 <a class="header-anchor vp-link" href="#_9-验收标准" aria-label="Permalink to &quot;9. 验收标准&quot;">​</a></h2><ul><li>异步加载整树后可单选、多选；多选 + <code>separator</code> 时对外为逗号字符串且空为 <code>&#39;&#39;</code>；否则为数组。</li><li><code>labelKey</code>/<code>valueKey</code>/<code>childrenKey</code> 映射正确；<code>filterable</code> 与 <code>filterNodeMethod</code> 透传生效。</li><li><code>reload()</code> 后数据更新；加载失败时触发 <code>load-error</code> 且不静默成功。</li></ul><hr><h2 id="_10-澄清结论速查" tabindex="-1">10. 澄清结论速查 <a class="header-anchor vp-link" href="#_10-澄清结论速查" aria-label="Permalink to &quot;10. 澄清结论速查&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>项</th><th>结论</th></tr></thead><tbody><tr><td>逗号模式命名</td><td><strong><code>separator</code></strong>（对齐 <code>C7Select</code>）</td></tr><tr><td>异步形态一期</td><td><strong>整树一次拉取</strong> + <code>resultKey</code></td></tr><tr><td>父子勾选默认</td><td><strong>EP 默认</strong></td></tr><tr><td><code>valueType === &#39;auto&#39;</code></td><td><strong>根列表首条</strong> <code>valueKey</code> 字段类型</td></tr><tr><td>首次请求</td><td><strong><code>autoLoad</code></strong>，与 <code>C7Select</code> 语义对齐</td></tr><tr><td>静态别名</td><td><strong><code>options</code> 同 <code>C7Select</code></strong></td></tr></tbody></table></div>',47)])])}const p=o(r,[["render",a]]);export{u as __pageData,p as default};
